    public RatePreview previewRate(String sheetId, Grade grade, BigDecimal pct) {
        Map<Long, Person> byId = new HashMap<>();
        for (Person p : people.findInListOrder(sheetId)) byId.put(p.getId(), p);
        int count = 0;
